def check(output, ctx):
    try:
        d = parse_json(output)
        if not isinstance(d, dict):
            return True
        low = [x.lower() for x in ctx['text'].split()]
        from collections import Counter
        c = Counter()
        for k in ["person", "location", "organization", "else"]:
            v = d.get(k, [])
            if isinstance(v, list):
                for e in v:
                    if isinstance(e, str):
                        c[" ".join(e.strip().lower().split())] += 1
        for s, cnt in c.items():
            et = s.split()
            n = len(et)
            if n == 0:
                continue
            occ = sum(1 for i in range(len(low) - n + 1) if low[i:i+n] == et)
            if occ and cnt > occ:
                return False
        return True
    except Exception:
        return True

